function mkEstimate(over = {}) {
  return {
    number: "", date: "", validThrough: "", status: "Draft",
    scope: "", notes: "",
    items: [],
    /* Good/Better/Best + optional upgrades. Deliberately additive:
       `items` stays the single flattened list every existing reader
       (estimateTotal, the PDF/doc builder, financials, commission calc,
       the portal) already reads — none of that had to change. `tiers`
       and `upgrades` are the AUTHORING structure; selecting a tier or
       toggling an upgrade re-flattens into `items` via
       applyEstimateSelection(). A job with no tiers configured (every
       existing job, until a rep sets this up) behaves exactly as
       before — tiers defaults to [], so applyEstimateSelection is a
       no-op and items is untouched. */
    tiers: [],            // [{ id, name, items: [...same shape as items] }]
    selectedTier: null,   // id of the active tier, or null = flat estimate (old behavior)
    upgrades: [],         // [{ id, desc, price, cost, selected }]
    concealed: [
      { id: "c1", desc: "Roof decking replacement (7/16\" OSB)", unit: "per 4×8 sheet", price: 0, on: true },
      { id: "c2", desc: "Plank decking replacement", unit: "per LF", price: 0, on: true },
      { id: "c3", desc: "Rafter sistering / repair", unit: "per rafter", price: 0, on: true },
      { id: "c4", desc: "Fascia replacement", unit: "per LF", price: 0, on: true },
    ],
    clientSig: null, sigAt: null, ...over,
  };
}
/* Re-flattens the active tier's items + any selected upgrades into
   est.items. Call this any time selectedTier or an upgrade's selected
   flag changes. Safe to call on an estimate with no tiers configured
   at all — falls straight through to the existing items unchanged. */
function applyEstimateSelection(est) {
  const tiers = est.tiers || [];
  const tier = tiers.find((t) => t.id === est.selectedTier);
  const base = tier ? tier.items : est.items;
  const upgrades = (est.upgrades || []).filter((u) => u.selected);
  const upgradeItems = upgrades.map((u) => ({
    id: u.id, desc: u.desc, qty: 1, unit: "ea", price: num(u.price), cost: num(u.cost),
    fromUpgrade: true,
  }));
  return [...base, ...upgradeItems];
}
/* Price one generated estimate line from the price list, converting the
   catalog's per-unit price into the line's unit with `factor` (the coverage
   constants: 3 bundles per SQ of shingles, 25 LF of cap per bundle, etc.).
   Returns null when nothing in the catalog matches, so the caller can leave
   the price at 0 and flag it rather than inventing a number. */
function catalogUnitPrice(priceList, keywords, factor) {
  if (!Array.isArray(priceList) || !priceList.length) return null;
  const hit = priceList.find((r) => {
    const hay = `${r.item || ""} ${r.sku || ""} ${r.category || ""}`.toLowerCase();
    return keywords.some((k) => hay.includes(k));
  });
  const base = hit ? num(hit.price) : 0;
  if (!base) return null;
  return Math.round(base * factor * 100) / 100;
}
/* Live supplier pricing (QXO, ABC Supply, Beacon, SRS…) — scaffold.
   A distributor account is stored per supplier so estimates can eventually
   pull the customer's real, account-specific price for a SKU. The pull
   itself must run server-side (the anon key can't hold a distributor API
   key), so this returns "pending" until a supplier-pricing Edge Function
   is deployed. Shape mirrors the Google-reviews stub. */
const SUPPLIER_OPTIONS = ["QXO", "ABC Supply", "Beacon", "SRS Distribution", "Other"];
async function fetchSupplierPricing(/* supplier, sku, account */) {
  // No server function yet — reads fall through to the manual price list.
  return { ok: false, pending: true, price: null };
}

