/* Flatten the county maps into jurisdiction records. Built once at
   module load rather than stored as literals, so adding a ZIP is a
   one-line change and the code basis can never drift between entries
   in the same state. */
function buildMarketJurisdictions() {
  const out = {};
  const add = (zip, city, county, state, suffixed) => {
    /* County names repeat across states — there are Warren, Montgomery,
       Hamilton and Greene counties in a dozen states each — so the
       department table is keyed by state and county together. Keying on
       the bare name returned an Ohio department for a New Jersey zip. */
    const dept = COUNTY_DEPARTMENTS[`${state}:${county}`] || null;
    /* Keys ending in a letter are disambiguators for towns sharing a
       ZIP with another entry; strip them for the real key. */
    const z = zip.replace(/[a-z]$/, "");
    /* A suffixed key must never displace a real one. "41042b" (Taylor Mill)
       was inserted before Boone County's real "41042" (Florence) and the
       first-wins guard then discarded Florence — sending that rep to the
       wrong county's building department. Real keys always win. */
    if (out[z] && !(out[z].suffixed && !suffixed)) return;
    const d = STATE_DEFAULTS[state];
    out[z] = {
      suffixed: !!suffixed,
      zip: z, city, county, state,
      codeName: d.codeName, codeEdition: d.codeEdition,
      adoption: d.adoption, permit: d.permit,
      inspector: dept
        ? { office: dept.office, phone: dept.phone, address: dept.address,
            web: dept.web, note: dept.note, except: dept.except, checked: dept.checked }
        : { office: "", phone: "", address: "" },
      needsContact: !dept,
      verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
    };
  };
  Object.entries(OH_COUNTY_ZIPS).forEach(([county, zips]) =>
    Object.entries(zips).forEach(([z, city]) => add(z, city, county, "OH", /[a-z]$/.test(z))));
  Object.entries(KY_COUNTY_ZIPS).forEach(([county, zips]) =>
    Object.entries(zips).forEach(([z, city]) => add(z, city, county, "KY", /[a-z]$/.test(z))));
  return out;
}
const MARKET_JURISDICTIONS = buildMarketJurisdictions();

function stateForZip(zip) {
  const p = parseInt(String(zip).slice(0, 3), 10);
  if (isNaN(p)) return null;
  const hit = ZIP_PREFIX_STATE.find((r) => p >= r.lo && p <= r.hi);
  return hit ? hit.state : null;
}
/* Returns { ...record, precision } — "verified" | "state" | null */
/* Office-verified inspector contacts, saved from the Code lookup
   screen. Held at module scope so every caller sees the same data
   without threading it through a dozen components; the app hydrates it
   from company settings on load. */
let JURIS_OVERRIDES = {};
function setJurisOverrides(map) { JURIS_OVERRIDES = map || {}; }

/* ZIPs looked up on demand and saved, so the database grows with use
   rather than needing every ZIP in the country shipped up front. */
let LEARNED_JURISDICTIONS = {};
function setLearnedJurisdictions(map) { LEARNED_JURISDICTIONS = map || {}; }

function resolveJurisdiction(zip) {
  const z = String(zip || "").trim();
  if (z.length !== 5) return null;
  const ov = JURIS_OVERRIDES[z];
  const exact = JURISDICTIONS[z];
  if (exact) {
    return ov
      ? { ...exact, inspector: { ...exact.inspector, ...ov }, needsContact: false,
          verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" }
      : { ...exact, precision: "verified" };
  }
  /* Markets we work: city and county are known, code basis is the
     state code, and the permitting office is filled in by the office
     the first time someone calls it. */
  /* ZIPs the app has looked up and saved. Checked after the curated
     lists so a hand-written record always wins. */
  const learned = LEARNED_JURISDICTIONS[z];
  if (learned) {
    return ov
      ? { ...learned, inspector: { ...learned.inspector, ...ov }, needsContact: false,
          verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" }
      : { ...learned, precision: learned.needsContact ? "learned" : "market" };
  }
  const mkt = MARKET_JURISDICTIONS[z];
  if (mkt) {
    if (ov) {
      return { ...mkt, inspector: { ...mkt.inspector, ...ov }, needsContact: false,
        verified: true, verifiedDetail: { date: ov.at || null, by: ov.by || null }, precision: "verified" };
    }
    return { ...mkt, precision: "market" };
  }
  const st = stateForZip(z);
  if (!st) return null;
  /* OH/KY/IL have validated defaults; every other state falls back to its
     adopted-code family so a job anywhere still resolves (no crash). */
  const adopt = STATE_CODE_ADOPTION[st];
  const d = STATE_DEFAULTS[st] || {
    codeName: codeNameForState(st), codeEdition: "Verify the adopted edition",
    adoption: adopt && adopt.local ? "Adopted locally — confirm the adopting jurisdiction." : "Confirm the current adopted edition and local amendments.",
    permit: "Confirm permit requirements with the local building department.",
    sources: ["ICC", "MUNICODE"],
  };
  return {
    zip: z, city: "", county: "", state: st,
    codeName: d.codeName, codeEdition: d.codeEdition, adoption: d.adoption, permit: d.permit,
    inspector: { office: "Local building department — not yet on file", phone: "", address: "" },
    /* Without this the card rendered as a populated record with a blank
       phone and hid the "find the building department" links — from the
       one group of users who have no other way to get them. */
    needsContact: true,
    verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
    precision: "state",
  };
}

/* Geoapify — address autocomplete + reverse geocoding.
   Free tier: 3,000 requests/day, commercial use permitted, no attribution
   required, results may be stored. Swap the key for an env var at deploy
   and lock it to your domain under Allowed Origins in the Geoapify console. */
const GEO_PROVIDER = {
  name: "geoapify",
  apiKey: (typeof window !== "undefined" && window.__GEOAPIFY_KEY__) || "d4895cd9d44b4229af2885ffa85e343e",
  base: "https://api.geoapify.com/v1/geocode",
  countries: "us",
};
const geoReady = () => !!(GEO_PROVIDER.apiKey && GEO_PROVIDER.name === "geoapify");

/* Type-ahead address suggestions. Returns [] on any failure so the form
   always stays usable — a dead API must never block writing a lead. */
/* Proximity bias for address search — the rep works one metro, so ranking
   results near where they already work fixes "it found the wrong city."
   Seeded from existing jobs on load and updated to each address they pick. */
let GEO_BIAS = null;
function setGeoBias(lat, lng) {
  if (lat != null && lng != null && !isNaN(+lat) && !isNaN(+lng)) GEO_BIAS = { lat: +lat, lng: +lng };
}
async function geoAutocomplete(text, signal) {
  if (!geoReady() || !text || text.trim().length < 3) return [];
  const bias = GEO_BIAS ? `&bias=proximity:${GEO_BIAS.lng},${GEO_BIAS.lat}` : "";
  const url = `${GEO_PROVIDER.base}/autocomplete?text=${encodeURIComponent(text)}`
    + `&filter=countrycode:${GEO_PROVIDER.countries}&limit=8${bias}&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url, { signal });
    if (!res.ok) return [];
    const data = await res.json();
    return (data.results || []).map((r) => ({
      id: r.place_id || `${r.lat},${r.lon}`,
      formatted: r.formatted || "",
      street: [r.housenumber, r.street].filter(Boolean).join(" ") || r.address_line1 || "",
      city: r.city || r.town || r.village || r.county || "",
      state: r.state_code || "",
      zip: r.postcode || "",
      lat: r.lat, lng: r.lon,
    }));
  } catch { return []; }
}

/* ------------------------------------------------------------------
   SLIPPY-MAP PROJECTION

   Web Mercator, the same scheme every raster tile server uses: the
   world is one 256px tile at zoom 0 and doubles each level, so a
   lat/lng maps to an absolute pixel on that grid and back again.

   These are pure functions on purpose — the map component's panning,
   pin placement and tap-to-drop all reduce to project/unproject, and
   pure math is the part worth testing directly rather than through a
   rendered map.
------------------------------------------------------------------- */
const TILE_SIZE = 256;
const MAX_LAT = 85.05112878;   // where Mercator goes infinite
function lngToWorldX(lng, z) {
  return ((lng + 180) / 360) * TILE_SIZE * Math.pow(2, z);
}
function latToWorldY(lat, z) {
  const clamped = Math.max(-MAX_LAT, Math.min(MAX_LAT, lat));
  const s = Math.sin((clamped * Math.PI) / 180);
  return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * TILE_SIZE * Math.pow(2, z);
}
function worldXToLng(x, z) {
  return (x / (TILE_SIZE * Math.pow(2, z))) * 360 - 180;
}
function worldYToLat(y, z) {
  const n = Math.PI - (2 * Math.PI * y) / (TILE_SIZE * Math.pow(2, z));
  return (180 / Math.PI) * Math.atan(Math.sinh(n));
}
/* Great-circle distance in METRES. Canvassing works at street scale —
   "is this tap the same house as that pin" is a 15 m question, and
   miles are the wrong unit to ask it in. */
function metresBetween(lat1, lng1, lat2, lng2) {
  const R = 6371000, rad = Math.PI / 180;
  const dLat = (lat2 - lat1) * rad, dLng = (lng2 - lng1) * rad;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * rad) * Math.cos(lat2 * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(a)));
}

/* Property records (year built, square footage) — a keyed provider (e.g.
   RentCast's free tier) auto-fills the fields; without a key the free
   county-records deep-link still works nationwide. Mirrors GEO_PROVIDER. */
const PROPERTY_PROVIDER = {
  name: "rentcast",
  apiKey: (typeof window !== "undefined" && window.__PROPERTY_KEY__) || "",
  base: "https://api.rentcast.io/v1/properties",
};
const propertyReady = () => !!PROPERTY_PROVIDER.apiKey;
/* Free, keyless: a scoped web search that lands on the county assessor /
   parcel record for the address. Works anywhere in the US. */
const countyRecordsLink = (address) =>
  `https://www.google.com/search?q=${encodeURIComponent(`${address} property record assessor parcel year built square feet`)}`;
const PROPERTY_CACHE = new Map();
async function fetchPropertyRecord(address) {
  if (!propertyReady() || !address) return null;
  const key = address.trim().toLowerCase();
  if (PROPERTY_CACHE.has(key)) return PROPERTY_CACHE.get(key);
  try {
    const res = await fetch(`${PROPERTY_PROVIDER.base}?address=${encodeURIComponent(address)}`,
      { headers: { "X-Api-Key": PROPERTY_PROVIDER.apiKey, Accept: "application/json" } });
    if (!res.ok) throw new Error("property");
    const data = await res.json();
    const r = Array.isArray(data) ? data[0] : data;
    const out = r ? {
      yearBuilt: r.yearBuilt || null,
      squareFeet: r.squareFootage || r.squareFeet || null,
      stories: r.stories || (r.features && r.features.floorCount) || null,
      lotSize: r.lotSize || null,
    } : null;
    PROPERTY_CACHE.set(key, out);
    return out;
  } catch (e) { return null; }
}

/* Coordinates -> street address. Used to stamp photos with a real address
   alongside the GPS fix, and to name a canvassing pin the moment it is
   dropped ("412 Oak St" is what a rep needs on screen, not a lat/lng).

   Cached because canvassing changed the call pattern: photo stamping
   asks once per photo, but a rep working a street drops pins minute
   after minute, and re-asking the provider for a house already looked
   up spends quota on an answer we hold. Keyed to ~1 m so the same door
   tapped twice is one lookup. */
const REVERSE_CACHE = new Map();
async function geoReverse(lat, lng) {
  if (!geoReady() || lat == null || lng == null) return null;
  const key = `${Math.round(lat * 1e5)},${Math.round(lng * 1e5)}`;
  if (REVERSE_CACHE.has(key)) return REVERSE_CACHE.get(key);
  const url = `${GEO_PROVIDER.base}/reverse?lat=${lat}&lon=${lng}&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const r = (data.results || [])[0];
    if (!r) return null;
    const out = {
      formatted: r.formatted || "",
      street: [r.housenumber, r.street].filter(Boolean).join(" ") || r.address_line1 || "",
      city: r.city || r.town || r.village || "",
      state: r.state_code || "",
      zip: r.postcode || "",
    };
    REVERSE_CACHE.set(key, out);
    return out;
  } catch { return null; }
}

/* Look up a ZIP we have never seen. Geoapify returns the county, which
   is the piece that matters: departments are keyed by county, so a new
   ZIP inside a county already on file resolves completely — office,
   phone, address and all — without anyone typing a thing. A ZIP in a
   new county resolves to city, county and the correct state code
   basis, leaving only the permitting office for a human to add. */
async function geoLookupZip(zip) {
  const z = String(zip || "").trim();
  if (!geoReady() || z.length !== 5) return null;
  const url = `${GEO_PROVIDER.base}/search?postcode=${encodeURIComponent(z)}`
    + `&filter=countrycode:${GEO_PROVIDER.countries}&type=postcode&limit=1&format=json&apiKey=${GEO_PROVIDER.apiKey}`;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data = await res.json();
    const r = (data.results || [])[0];
    if (!r) return null;
    const state = r.state_code || "";
    /* Geoapify returns "Hamilton County" or sometimes "Hamilton"; both
       are normalised so the department map matches either way. */
    const rawCounty = r.county || "";
    const county = rawCounty && !/county$/i.test(rawCounty) ? `${rawCounty} County` : rawCounty;
    return {
      zip: z, city: r.city || r.town || r.village || "", county, state,
      dept: COUNTY_DEPARTMENTS[`${state}:${county}`] || null,
      /* Ohio/Kentucky/Illinois have a validated code library; everywhere else
         we still resolve the state's adopted code, just flagged to verify. */
      curated: !!STATE_DEFAULTS[state],
    };
  } catch { return null; }
}

/* Build a jurisdiction record from a lookup result, ready to save. Works for
   any state: curated states (OH/KY/IL) use the validated defaults; the rest
   fall back to the state's adopted-code family with a verify note. */
function jurisdictionFromLookup(hit) {
  const adopt = STATE_CODE_ADOPTION[hit.state];
  const d = STATE_DEFAULTS[hit.state] || {
    codeName: codeNameForState(hit.state),
    codeEdition: "Verify the adopted edition",
    adoption: adopt && adopt.local
      ? "Adopted locally — confirm the adopting municipality/county for this address."
      : "Confirm the current adopted edition and any local amendments.",
    permit: "Confirm permit requirements with the local building department.",
    sources: ["ICC", "MUNICODE"],
  };
  const dept = hit.dept;
  return {
    zip: hit.zip, city: hit.city, county: hit.county, state: hit.state,
    codeName: d.codeName, codeEdition: d.codeEdition, adoption: d.adoption, permit: d.permit,
    inspector: dept
      ? { office: dept.office, phone: dept.phone, address: dept.address,
          web: dept.web, note: dept.note, except: dept.except, checked: dept.checked }
      : { office: "", phone: "", address: "" },
    needsContact: !dept,
    verified: false, sources: d.sources, verifiedDetail: { date: null, by: null },
  };
}

function captureLocation() {
  return new Promise((resolve) => {
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      resolve({ ok: false, reason: "Geolocation not supported on this device." });
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({
        ok: true,
        lat: +pos.coords.latitude.toFixed(6),
        lng: +pos.coords.longitude.toFixed(6),
        accuracy: Math.round(pos.coords.accuracy),
        at: new Date().toISOString(),
      }),
      (err) => resolve({ ok: false, reason: err.code === 1 ? "Location permission denied." : "Could not get a location fix." }),
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  });
}
const fmtCoord = (lat, lng) => `${lat.toFixed(5)}, ${lng.toFixed(5)}`;
/* Provider-neutral links — work with no API key, open in the user's map app. */
const mapLinkForCoords = (lat, lng) => `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
const mapLinkForAddress = (addr) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(addr)}`;
const directionsLink = (addr) => `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(addr)}`;
/* Directions in the rep's map app of choice. All three are https universal
   links that hand off to the installed app on an iOS home-screen PWA. */
const directionsAppleLink = (addr) => `https://maps.apple.com/?daddr=${encodeURIComponent(addr)}`;
const directionsWazeLink = (addr) => `https://waze.com/ul?q=${encodeURIComponent(addr)}&navigate=yes`;
const MAP_PROVIDERS = [
  { id: "google", name: "Google Maps", link: directionsLink },
  { id: "apple", name: "Apple Maps", link: directionsAppleLink },
  { id: "waze", name: "Waze", link: directionsWazeLink },
];
/* Remembered default map app — last one used wins, stored per device.
   Guarded so it's a no-op under jsdom/SSR where localStorage may be absent. */
const MAP_PREF_KEY = "ridgeline.mapProvider";
const getMapPref = () => { try { return localStorage.getItem(MAP_PREF_KEY) || "google"; } catch (e) { return "google"; } };
const setMapPref = (id) => { try { localStorage.setItem(MAP_PREF_KEY, id); } catch (e) { /* ignore */ } };
const staticMapEmbed = (lat, lng) => {
  const d = 0.004;
  return `https://www.openstreetmap.org/export/embed.html?bbox=${lng - d}%2C${lat - d}%2C${lng + d}%2C${lat + d}&layer=mapnik&marker=${lat}%2C${lng}`;
};
const fmtStamp = (iso) => {
  try {
    return new Date(iso).toLocaleString(undefined, {
      month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit",
    });
  } catch { return iso; }
};

const money = (n) =>
  (n < 0 ? "-$" : "$") + Math.abs(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
/* Whole dollars, for the big customer-facing numbers. "$20,911" reads as a
   price; "$20,911.00" reads as an invoice line. */
const money0 = (n) =>
  (n < 0 ? "-$" : "$") + Math.abs(Math.round(n)).toLocaleString();
