    note: x.note, srcId: x.srcId || x.src, sourceUrl: x.sourceUrl || x.source,
    asOf: x.asOf || (x.verifiedDetail && x.verifiedDetail.date) || x.checked || null,
    verifiedBy: x.verifiedBy || (x.verifiedDetail && x.verifiedDetail.by) || null,
