  const coApproved = (Array.isArray(job.changeOrders) ? job.changeOrders : [])
    .filter((c) => c.status === "Approved").reduce((a2, c) => a2 + coTotal(c), 0);
  const supApproved = (Array.isArray((job.claim || {}).supplements) ? job.claim.supplements : [])
