/* Map a free-text price-sheet row to a known pay code, so an uploaded
   subcontractor sheet drives pay automatically. Anything unrecognized is
   kept as a flat add-on. */
function subCodeFor(text) {
  const s = String(text || "").toLowerCase();
  /* Order matters: a base install line often names a pitch range
     ("install, 2/12 to 8/12 pitch") — it must NOT be read as a steep
     charge. Match the explicit steep/mansard and tear-off wording first,
     then the base install, then a bare "steep/pitch" as a last resort. */
  if (/mansard|steep\s*charge/.test(s)) return "steep_per_square";
  if (/additional layer|layer removal|tear|\brip\b/.test(s)) return "tearoff_per_square";
  if (/(3|three|3\+).*stor/.test(s)) return "story_3";
  if (/(2|two|second).*stor/.test(s)) return "story_2";
  if (/chimney/.test(s)) {
    if (/small/.test(s)) return "chimney_small";
    if (/large/.test(s)) return "chimney_large";
    return "chimney_medium";
  }
  /* Base install = an install line for the field/roof (optionally naming a
     pitch range like "2/12 to 8/12"), but NOT an accessory install (skylight,
     vent, flashing…). This catches "Shingle install, 2/12 to 8/12 pitch" and
     "Install, 2/12 to 8/12 pitch" without misreading either as a steep charge. */
  if (/install/.test(s)
      && /(shingle|roof|field|base|\d+\s*\/\s*\d+)/.test(s)
      && !/skylight|vent|flash|boot|pipe|jack|drip|ridge|starter|solar|gutter|siding|fascia|soffit|chimney/.test(s))
    return "per_square";
  if (/steep|pitch/.test(s)) return "steep_per_square";
  return null;
}
const SUB_RATE_LABELS = {
  per_square: "Install (per square)", steep_per_square: "Steep charge (per square)",
  tearoff_per_square: "Tear-off (per square, per extra layer)", story_2: "2-story adder",
  story_3: "3+ story adder", chimney_small: "Chimney — small", chimney_medium: "Chimney — medium",
  chimney_large: "Chimney — large",
};
function subRate(crew, code) {
  const row = ((crew && crew.rateCard) || []).find((r) => r.code === code);
  return row ? num(row.price) : 0;
}
/* Figure a subcontractor's pay for a job from their uploaded rate card and
   the job's installed squares + conditions. Returns a transparent line
   breakdown so the office can see exactly how the number was built. */
/* Compliance docs (W-9, COI, license) that are expired or expiring within 30
   days, so a sub with lapsed paperwork gets flagged before they're paid. */
function crewDocAlerts(crew, today) {
  const t = today || todayIso();
  const soon = isoLocal(new Date(new Date(t + "T12:00:00").getTime() + 30 * 86400000));
  return ((crew && crew.docs) || [])
    .filter((d) => d.expires)
    .map((d) => ({ name: d.name, type: d.type || "", expires: d.expires, status: d.expires < t ? "expired" : (d.expires <= soon ? "expiring" : "ok") }))
    .filter((d) => d.status !== "ok");
}
/* Jobs where this crew is still owed money — a confirmed or submitted
   invoice that has not been marked paid. Exactly the status set the
   Crew payouts "Subs to pay" queue treats as owed, so the two agree.
   Deleting a crew is blocked on this: the invoice would stay in that
   queue (and in the Home ready-to-pay count) while SubInvoiceCard,
   which is the only place it can be marked paid, renders solely for an
   assigned crew — leaving a payable nothing in the UI could ever
   clear. Settle it first, then the crew can go. */
function unpaidSubInvoiceJobs(jobs, crewId) {
  return (jobs || []).filter((j) => j.crewId === crewId && j.subInvoice
    && ["confirmed", "submitted"].includes(j.subInvoice.status));
}
/* Per-job subcontractor invoice — a draft that starts from what we can compute
   and stays editable until it's confirmed after install (actuals change:
   extra decking, dump fees, etc.). status: draft → needs_review → confirmed →
   submitted → paid. */
function mkSubInvoice(over = {}) {
  return {
    status: "draft", lines: [], poNumber: "", terms: "", dueDate: "",
    reviewedBy: "", reviewedAt: "", confirmedBy: "", confirmedAt: "", submittedAt: "", paidAt: "", ...over,
  };
}
function subInvoiceTotal(inv) {
  return ((inv && inv.lines) || []).reduce((a, l) => a + num(l.qty) * num(l.price), 0);
}
/* Due date from payment terms ("Net 15" → 15 days out; "Due on receipt" → now). */
function dueFromTerms(terms, from) {
  const base = from || todayIso();
  const m = /net\s*(\d+)/i.exec(String(terms || ""));
  const days = m ? parseInt(m[1], 10) : 0;
  return isoLocal(new Date(new Date(base + "T12:00:00").getTime() + days * 86400000));
}
/* Seed the lines we CAN compute from the crew's rate card + the job's installed
   squares and work-order conditions; the rest are added from the priced menu by
   hand. Each seeded line stays fully editable (source: "auto"). */
function buildSubInvoiceDraft(job, crew) {
  const inv = mkSubInvoice({ terms: (crew && crew.payment && crew.payment.terms) || "Net 15" });
  const cov = installedSquares(generateRoofingMaterials(job.measurements));
  const sq = cov ? cov.total : 0;
  const wo = job.workOrder || {};
  const lines = [];
  const add = (category, label, qty, unit, price) => { if (price && qty) lines.push({ id: uid("sil"), category, label, qty, unit, price, notes: "", reimbursable: false, source: "auto" }); };
  add("Shingle Installation", "Shingle install", sq, "SQ", subRate(crew, "per_square"));
  if (wo.steep) add("Shingle Installation", "Steep charge", sq, "SQ", subRate(crew, "steep_per_square"));
  const layers = parseInt(wo.layers || (job.checklist || {}).layers, 10) || 1;
  if (layers > 1) add("Shingle Installation", `Additional layer removal (${layers - 1})`, sq * (layers - 1), "SQ", subRate(crew, "tearoff_per_square"));
  /* The story adders. subCodeFor parses story_2 / story_3 out of the crew's
     uploaded rate card, but the draft builder never read wo.stories — so
     every multi-story sub invoice went out short by the adder. The rate was
     captured and then ignored. */
  if (wo.stories === "2") add("Access", "2-story adder", 1, "job", subRate(crew, "story_2"));
  if (wo.stories === "3+") add("Access", "3+ story adder", 1, "job", subRate(crew, "story_3"));
  const chim = (wo.chimney || {}).size;
  if (chim && chim !== "none") add("Chimney Flashing", `Chimney flashing (${chim})`, 1, "job", subRate(crew, `chimney_${chim}`));
  inv.lines = lines;
  return inv;
}

/* ================================================================
   AUTH ADAPTER
   When the app is deployed with Supabase credentials, src/main.jsx
   puts a real auth client on window.__AUTH__ and everything below
   runs against it. With no backend present the app falls back to the
   demo account picker so it still previews and demos.
   ================================================================ */
const AUTH = () => (typeof window !== "undefined" ? window.__AUTH__ : null);
const liveAuth = () => !!AUTH();
/* Set once the signed-in user's profile loads (see the boot-hydrate
   effect). Storage object keys are prefixed with this so the
   tenant-scoped write/update/delete Storage policies (migration 026)
   have something to check — RLS on storage.objects has no tenant_id
   column to key off, only the object path. */
const currentTenantId = () => (typeof window !== "undefined" ? window.__TENANT_ID__ || null : null);
/* Map a database profile row onto the shape the UI already uses. */
const fromProfile = (row) => ({
  id: row.id, name: row.name, email: row.email, phone: row.phone || "",
  role: row.role, title: row.title || "", active: row.active,
  commissionRate: row.commission_rate != null ? Number(row.commission_rate) : 60,
  addedAt: row.added_at || "", tenantId: row.tenant_id || null,
  permissionOverrides: row.permission_overrides || {},
});
const toProfile = (u) => ({
  name: u.name, email: u.email, phone: u.phone || null, role: u.role,
  title: u.title || null, commission_rate: u.commissionRate ?? 60, active: u.active,
  permission_overrides: u.permissionOverrides || {},
});

/* ================================================================
   SHARED UI
   ================================================================ */
/* Neutral tokens resolve to CSS variables (defined in index.html) so a
   dark/light switch is a single data-theme flip on <html> — every S.* read
   and every captured style const (inputStyle etc.) repaints via the cascade,
   with no re-render. `card` is the surface white that darkens in dark mode. */
const S = { ink: "var(--rl-ink)", sub: "var(--rl-sub)", line: "var(--rl-line)", bg: "var(--rl-bg)", soft: "var(--rl-soft)", card: "var(--rl-card)" };
/* Live theme. The root component copies brand colors in on every render,
   and because inline styles read these properties at render time, a color
   change in Branding repaints the whole app immediately. */
const T = { primary: "#20242A", accent: "#0A9E98", accentSoft: "#E3F5F4" };
function softOf(hex) {
  try {
    const n = parseInt(hex.slice(1), 16);
    const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    const mix = (c) => Math.round(c + (255 - c) * 0.88);
    return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
  } catch { return "#EAF2FD"; }
}

/* Donut chart — pure CSS conic-gradient, no charting library. Built
   for proportion-of-a-whole breakdowns (revenue by source, job cost
   mix) where a ranked list alone doesn't give an at-a-glance sense of
   share. Deliberately paired with the underlying numbers wherever it's
   used, never standing alone — a donut answers "roughly what share,"
   a table answers "exactly how much"; people need both. */
function DonutChart({ data, size = 132, thickness = 18, centerLabel, centerValue }) {
  const total = data.reduce((s, d) => s + Math.max(0, d.value), 0);
  let acc = 0;
  const stops = data.map((d) => {
    const pct = total > 0 ? (Math.max(0, d.value) / total) * 100 : 0;
    const start = acc;
    acc += pct;
    return `${d.color} ${start}% ${acc}%`;
  });
  const gradient = total > 0 && stops.length
    ? `conic-gradient(${stops.join(", ")})`
    : `conic-gradient(${S.line} 0% 100%)`;
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 18, flexWrap: "wrap" }}>
      <div style={{
        position: "relative", width: size, height: size, borderRadius: "50%",
        background: gradient, flexShrink: 0,
      }}>
        <div style={{
          position: "absolute", inset: thickness, borderRadius: "50%", background: S.card,
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
        }}>
          {centerValue != null && <div style={{ fontSize: 15, fontWeight: 800, color: S.ink }}>{centerValue}</div>}
          {centerLabel && <div style={{ fontSize: 10, color: S.sub, textAlign: "center", lineHeight: 1.3 }}>{centerLabel}</div>}
        </div>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, minWidth: 0, flex: 1 }}>
        {data.map((d) => {
          const pct = total > 0 ? Math.round((Math.max(0, d.value) / total) * 100) : 0;
          return (
            <div key={d.label} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 12.5 }}>
              <span style={{ width: 9, height: 9, borderRadius: 3, background: d.color, flexShrink: 0 }} />
              <span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: S.ink, flex: 1 }}>{d.label}</span>
              <span style={{ color: S.sub, fontWeight: 700, flexShrink: 0 }}>{pct}%</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
/* A small fixed palette so charts stay visually consistent everywhere
   they're used, rather than each call site inventing its own colors. */
const DONUT_PALETTE = ["#0A9E98", "#1B6DE0", "#F59E0B", "#7C3AED", "#EC4899", "#177245", "#B42318", "#5B6470"];

function Chip({ children, tone = "gray" }) {
  const tones = {
    gray: { bg: "var(--rl-gray-bg)", fg: "var(--rl-gray-fg)" },
    blue: { bg: T.accentSoft, fg: T.accent },
    green: { bg: "var(--rl-green-bg)", fg: "var(--rl-green-fg)" },
    red: { bg: "var(--rl-red-bg)", fg: "var(--rl-red-fg)" },
    amber: { bg: "var(--rl-amber-bg)", fg: "var(--rl-amber-fg)" },
    slate: { bg: "var(--rl-slate-bg)", fg: T.primary },
  };
  const t = tones[tone] || tones.gray;
  return (
    <span style={{
      background: t.bg, color: t.fg, fontSize: 12, fontWeight: 600,
      padding: "3px 10px", borderRadius: 999, display: "inline-block",
      alignSelf: "flex-start", maxWidth: "100%", wordBreak: "break-word", lineHeight: 1.35,
    }}>{children}</span>
  );
}

function Btn({ children, kind = "primary", onClick, style, small, disabled, ...props }) {
  const base = {
    display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 8,
    border: "1px solid transparent", borderRadius: 10, cursor: disabled ? "not-allowed" : "pointer",
    fontWeight: 600, fontSize: small ? 13 : 15,
    padding: small ? "7px 12px" : "11px 18px",
    opacity: disabled ? 0.5 : 1,
  };
  const kinds = {
    primary: { background: T.accent, color: "#fff" },
    dark: { background: T.primary, color: "#fff" },
    ghost: { background: S.card, color: S.ink, border: `1px solid ${S.line}` },
    soft: { background: T.accentSoft, color: T.accent },
    danger: { background: S.card, color: "#B42318", border: `1px solid ${S.line}` },
    green: { background: "#177245", color: "#fff" },
  };
  return (
    <button {...props} disabled={disabled} onClick={disabled ? undefined : onClick} style={{ ...base, ...kinds[kind], ...style }}>
      {children}
    </button>
  );
}

function Field({ label, children, hint }) {
  return (
    <label style={{ display: "block", marginBottom: 14 }}>
      <div style={{ fontSize: 13, fontWeight: 600, color: S.ink, marginBottom: 6 }}>{label}</div>
      {children}
      {hint && <div style={{ fontSize: 12, color: S.sub, marginTop: 5 }}>{hint}</div>}
    </label>
  );
}
const inputStyle = {
  width: "100%", boxSizing: "border-box", padding: "11px 13px", fontSize: 15,
  border: `1px solid ${S.line}`, borderRadius: 10, background: S.card, color: S.ink, outline: "none",
  fontFamily: "inherit",
};
const selStyle = { ...inputStyle, appearance: "auto" };

/* ==================================================================
   MONEY INPUT

   Every field that holds dollars shows them the way an accountant
   writes them: a leading $, thousands separators, and two decimals,
   right-aligned on tabular figures so columns line up.

   Formatting happens on blur, never on keystroke. A field that
   reformats as you type is unusable — "1" becomes "$1.00" and there
   is no way to reach "12". So while the field has focus it shows the
   plain number and behaves like an ordinary input; the moment you
   leave, it settles into accounting format.

   Negative values render "-$500.00" rather than the accounting
   parenthesis, to match money() everywhere else in the app. A number
   that reads one way in an input and another way in the total below
   it is worse than either convention.

   onChange receives the raw string, exactly as the plain inputs it
   replaces did, so call sites keep their own num() conversion.
================================================================== */
function MoneyInput({ value, onChange, disabled, style, placeholder = "$0.00", ...rest }) {
  const [editing, setEditing] = useState(false);
  const [raw, setRaw] = useState("");
  const blank = value === "" || value === null || value === undefined;
  const shown = editing ? raw : (blank ? "" : money(moneyNum(value)));
  return (
    <input
      {...rest}
      style={{ textAlign: "right", fontVariantNumeric: "tabular-nums", ...style }}
      inputMode="decimal"
      disabled={disabled}
      placeholder={placeholder}
      value={shown}
      onFocus={(e) => {
        setRaw(blank ? "" : String(moneyNum(value)));
        setEditing(true);
        /* Select on entry so tapping a filled field and typing replaces
           it, rather than appending to "1,234.56". */
        const el = e.target;
        setTimeout(() => { try { el.select(); } catch (err) { /* not selectable */ } }, 0);
      }}
      onChange={(e) => { setRaw(e.target.value); onChange(e.target.value); }}
      onBlur={() => {
        setEditing(false);
        /* Normalise what's stored: "1,234.56" and "$1,234.56" both
           settle to 1234.56, and a field cleared to nothing stays
           empty rather than becoming a hard zero. */
        onChange(String(raw).trim() === "" ? "" : String(moneyNum(raw)));
      }}
    />
  );
}
/* iOS renders type=date taller than a text input and ignores a fixed
   height, which overlapped the neighbouring field. Neutralising the
   native appearance and using minHeight keeps it in its column. */
const dateInputStyle = {
  ...inputStyle, WebkitAppearance: "none", MozAppearance: "none", appearance: "none",
  minHeight: 44, boxSizing: "border-box", width: "100%", minWidth: 0,
};

/* testId is forwarded because Card otherwise silently swallows every
   prop it doesn't name — a data-testid written on a Card looked right
   in the source and never reached the DOM, which is exactly the kind
   of thing that makes a passing test meaningless. */
function Card({ children, style, pad = 18, onClick, testId }) {
  return (
    <div onClick={onClick} data-testid={testId} style={{ background: S.card, border: `1px solid ${S.line}`, borderRadius: 14, padding: pad, ...style }}>
      {children}
    </div>
  );
}
function CardTitle({ children, right }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
      <div style={{ fontSize: 15, fontWeight: 700, color: S.ink }}>{children}</div>
      {right}
    </div>
  );
}
function KV({ k, v, strong }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 12, padding: "7px 0" }}>
      <span style={{ fontSize: 13, color: S.sub }}>{k}</span>
      <span style={{ fontSize: 13, fontWeight: strong ? 800 : 600, color: S.ink, textAlign: "right" }}>{v}</span>
    </div>
  );
}

/* Merged from the Ridgeline repo. */
function Callout({ label, children, tone = "amber" }) {
  const map = {
    amber: ["var(--rl-amber-bg)", "var(--rl-amber-fg)"],
    red: ["var(--rl-red-bg)", "var(--rl-red-fg)"],
    green: ["var(--rl-green-bg)", "var(--rl-green-fg)"],
  };
  const [bg, fg] = map[tone] || map.amber;
  return (
    <div style={{ background: bg, borderLeft: `3px solid ${fg}`, borderRadius: 8, padding: "12px 14px", marginTop: 12 }}>
      {label && <div style={{ fontSize: 13, fontWeight: 800, color: fg, marginBottom: 6 }}>{label}</div>}
      <div style={{ fontSize: 14, color: S.ink, lineHeight: 1.55 }}>{children}</div>
    </div>
  );
}
function Bullets({ items }) {
  return (
    <ul style={{ margin: "6px 0 0", paddingLeft: 18 }}>
      {items.map((t, i) => (
        <li key={i} style={{ fontSize: 14, color: S.ink, lineHeight: 1.55, marginBottom: 6 }}>{t}</li>
      ))}
    </ul>
  );
}
function SourceLink({ srcId }) {
  const s = SOURCES[srcId];
  if (!s) return null;
  return (
    <a href={s.url} target="_blank" rel="noreferrer" style={{
      display: "inline-flex", alignItems: "center", gap: 6, textDecoration: "none",
      border: `1px solid ${S.line}`, borderRadius: 999, padding: "6px 12px",
      fontSize: 12.5, fontWeight: 700, color: T.accent, background: S.card, marginTop: 8, marginRight: 8,
    }}>
      <ExternalLink size={13} /> {s.name}
    </a>
  );
}

/* The one way a citation renders. The tone is computed from the fact's
   own confidence rather than passed in, so a caller cannot paint an
   unconfirmed value in the verified style — which is exactly how a
   placeholder phone number ended up under a green "Verified" chip.

   An `unknown` fact renders the pointer instead of the value: who would
   know, and a link to them. Silence with a next step beats a guess. */
function Cited({ fact: f, compact = false, style }) {
  const x = asFact(f);
  const tone = factTone(x);
  if (!x.value) {
    return (
      <span style={{ display: "inline-flex", alignItems: "center", gap: 6, flexWrap: "wrap", ...style }}>
        <Chip tone="gray">{FACT_LABEL.unknown}</Chip>
        {x.note && <span style={{ fontSize: 11.5, color: S.sub }}>{x.note}</span>}
        {x.srcId ? <SourceLink srcId={x.srcId} /> : null}
        {!x.srcId && x.sourceUrl ? <AssistLink href={x.sourceUrl}>{x.sourceName || "Where to check"}</AssistLink> : null}
      </span>
    );
  }
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 6, flexWrap: "wrap", ...style }}>
      <Chip tone={tone}>{x.value}</Chip>
      {!compact && x.confidence !== "verified" && (
        <span style={{ fontSize: 11, fontWeight: 700, color: tone === "blue" ? T.accent : "#92600A" }}>
          {FACT_LABEL[x.confidence]}
        </span>
      )}
      {!compact && x.confidence === "verified" && x.asOf && (
        <span style={{ fontSize: 11, color: S.sub }}>Verified {x.asOf}{x.verifiedBy ? ` · ${x.verifiedBy}` : ""}</span>
      )}
      {!compact && x.srcId ? <SourceLink srcId={x.srcId} /> : null}
    </span>
  );
}

/* Municode hosts most municipal codes of ordinances. Their URLs are
   library.municode.com/<state-abbr>/<city-slug>; with no city we land on
   the state index so the rep can pick the municipality. Slugs are lower-
   case with underscores for spaces (e.g. "Forest Park" -> forest_park). */
function municodeUrl(state, city) {
  const st = String(state || "").trim().toLowerCase();
  if (!/^[a-z]{2}$/.test(st)) return SOURCES.MUNICODE.url;
  const slug = String(city || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  return slug ? `https://library.municode.com/${st}/${slug}` : `https://library.municode.com/${st}`;
}
/* No free nationwide building-department directory exists, so we hand the
   rep a scoped web search that lands on the right office nearly every time.
   Honest assist, not a database. */
function deptSearchUrl(city, state) {
  const q = [city, state, "building department permits phone"].filter(Boolean).join(" ");
  return `https://www.google.com/search?q=${encodeURIComponent(q)}`;
}
/* A pill link that matches SourceLink's look but points anywhere. */
function AssistLink({ href, children }) {
  return (
    <a href={href} target="_blank" rel="noreferrer" style={{
      display: "inline-flex", alignItems: "center", gap: 6, textDecoration: "none",
      border: `1px solid ${S.line}`, borderRadius: 999, padding: "6px 12px",
      fontSize: 12.5, fontWeight: 700, color: T.accent, background: S.card, marginTop: 8, marginRight: 8,
    }}>
      <ExternalLink size={13} /> {children}
    </a>
  );
}

/* ================================================================
   ADDRESS AUTOCOMPLETE — debounced Geoapify typeahead.
   Degrades to a plain text field if the API is unreachable, so a
   lead can always be written.
   ================================================================ */
function AddressAutocomplete({ value, onChange, onPick, placeholder }) {
  const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [hi, setHi] = useState(-1);
  const abortRef = useRef(null);
  const timerRef = useRef(null);
  const blurRef = useRef(null);

  useEffect(() => () => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (abortRef.current) abortRef.current.abort();
    if (blurRef.current) clearTimeout(blurRef.current);
  }, []);

  const query = (text) => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (!geoReady() || text.trim().length < 3) { setItems([]); setOpen(false); return; }
    timerRef.current = setTimeout(async () => {
      if (abortRef.current) abortRef.current.abort();
      const ctl = new AbortController();
      abortRef.current = ctl;
      setBusy(true);
      const res = await geoAutocomplete(text, ctl.signal);
      setBusy(false);
      setItems(res); setHi(-1);
      setOpen(res.length > 0);
    }, 280);
  };

  const choose = (it) => {
    setOpen(false); setItems([]);
    setGeoBias(it.lat, it.lng); // next search biases toward where this rep just worked
    onPick(it);
  };

  return (
    <div style={{ position: "relative" }}>
      <div style={{ position: "relative" }}>
        <input
          style={{ ...inputStyle, paddingRight: 36 }}
          value={value}
          placeholder={placeholder}
          autoComplete="off"
          onChange={(e) => { onChange(e.target.value); query(e.target.value); }}
          onFocus={() => items.length && setOpen(true)}
          onBlur={() => { blurRef.current = setTimeout(() => setOpen(false), 160); }}
          onKeyDown={(e) => {
            if (!open || !items.length) return;
            if (e.key === "ArrowDown") { e.preventDefault(); setHi((h) => (h + 1) % items.length); }
            else if (e.key === "ArrowUp") { e.preventDefault(); setHi((h) => (h - 1 + items.length) % items.length); }
            else if (e.key === "Enter" && hi >= 0) { e.preventDefault(); choose(items[hi]); }
            else if (e.key === "Escape") setOpen(false);
          }}
        />
        <span style={{ position: "absolute", right: 11, top: "50%", transform: "translateY(-50%)", display: "flex" }}>
          {busy ? <RefreshCw size={15} color="#9CA3AF" /> : <MapPin size={15} color="#C7CBD1" />}
        </span>
      </div>
      {open && items.length > 0 && (
        <div style={{
          position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, zIndex: 30,
          background: S.card, border: `1px solid ${S.line}`, borderRadius: 12,
          boxShadow: "0 10px 28px rgba(17,24,39,.14)", overflow: "hidden", maxHeight: 260, overflowY: "auto",
        }}>
          {items.map((it, i) => (
            <button key={it.id} type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => choose(it)}
              onMouseEnter={() => setHi(i)}
              style={{
                display: "flex", alignItems: "flex-start", gap: 10, width: "100%", textAlign: "left",
                border: "none", cursor: "pointer", padding: "11px 13px",
                background: hi === i ? T.accentSoft : S.card,
                borderTop: i ? `1px solid ${S.line}` : "none",
              }}>
              <MapPin size={14} color={T.accent} style={{ flexShrink: 0, marginTop: 2 }} />
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: "block", fontSize: 14, fontWeight: 600, color: S.ink }}>
                  {it.street || it.formatted}
                </span>
                <span style={{ display: "block", fontSize: 12, color: S.sub, marginTop: 2 }}>
                  {[it.city, it.state, it.zip].filter(Boolean).join(", ")}
                </span>
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function Sheet({ open, onClose, title, children, footer, wide, tall, center = true }) {
  /* Escape closing a dialog is the instinct a keyboard/trackpad user
     reaches for before hunting for the X — every other dismissible
     surface in this file (the combobox dropdown, inline rename fields)
     already honours it; Sheet never did. The listener has to attach
     even when closed (hooks can't be conditional) — it just no-ops. */
  useEffect(() => {
    if (!open) return;
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose]);
  if (!open) return null;
  /* Dialogs float centered by default (pass center={false} for a bottom sheet).
     `center` renders a floating, vertically-centered dialog (rounded on all
     sides, insets from the screen edges) instead of the default bottom sheet
     that's anchored to the bottom edge. */
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 60, background: "rgba(17,24,39,.45)",
      display: "flex", alignItems: center ? "center" : "flex-end", justifyContent: "center",
      padding: center ? 20 : 0, boxSizing: "border-box",
    }} onClick={onClose}>
      <div onClick={(e) => e.stopPropagation()} style={{
        background: S.card, width: "100%", maxWidth: wide ? 760 : 560,
        /* `vh` is the layout viewport, which on iOS Safari can be taller
           than what's actually on screen while the address bar is
           showing — the footer (the button that submits the sheet) would
           render below the real visible area with no way to reach it,
           since this outer overlay has no scroll of its own. `dvh` tracks
           the real, currently-visible viewport instead. */
        maxHeight: center ? "82dvh" : "90dvh", minHeight: tall ? "55dvh" : undefined,
        borderRadius: center ? 18 : "18px 18px 0 0", display: "flex", flexDirection: "column",
        boxShadow: center ? "0 24px 60px rgba(17,24,39,.28)" : undefined,
      }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "18px 20px 12px" }}>
          <div style={{ fontSize: 20, fontWeight: 700, color: S.ink }}>{title}</div>
          <button onClick={onClose} aria-label="Close" style={{
            border: "none", background: S.soft, borderRadius: 999, width: 34, height: 34,
            display: "grid", placeItems: "center", cursor: "pointer", color: S.ink,
          }}><X size={17} /></button>
        </div>
        <div style={{
          overflowY: "auto", padding: "4px 20px 20px", flex: 1,
          WebkitOverflowScrolling: "touch", overscrollBehavior: "contain",
        }}>{children}</div>
        {footer && <div style={{ padding: "12px 20px 20px", borderTop: `1px solid ${S.line}` }}>{footer}</div>}
      </div>
    </div>
  );
}

function Toast({ msg }) {
  if (!msg) return null;
  return (
    <div style={{
      position: "fixed", bottom: 96, left: "50%", transform: "translateX(-50%)",
      background: "#111827", color: "#fff", borderRadius: 999, padding: "10px 18px",
      fontSize: 14, fontWeight: 600, zIndex: 90, whiteSpace: "nowrap",
      /* Purely informational, never itself tappable — without this its
         screen rect can sit on top of a Sheet's footer button (e.g. an
         Add-appointment save) and silently swallow a real tap meant for
         what's underneath. */
      pointerEvents: "none",
    }}>{msg}</div>
  );
}

/* ================================================================
   SIGNATURE PAD — canvas capture, stored as data URL with timestamp
   ================================================================ */
function SignaturePad({ open, onClose, title, onApply }) {
  const ref = useRef(null);
  const drawing = useRef(false);
  const dirty = useRef(false);
  useEffect(() => {
    if (!open) return;
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d");
    ctx.fillStyle = "#fff";
    ctx.fillRect(0, 0, cv.width, cv.height);
    ctx.strokeStyle = "#111827";
    ctx.lineWidth = 2.4;
    ctx.lineCap = "round";
    dirty.current = false;
  }, [open]);
  const pos = (e) => {
    const cv = ref.current, r = cv.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: ((t.clientX - r.left) / r.width) * cv.width, y: ((t.clientY - r.top) / r.height) * cv.height };
  };
  const start = (e) => {
    e.preventDefault();
    drawing.current = true;
    const ctx = ref.current.getContext("2d");
    const p = pos(e);
    ctx.beginPath(); ctx.moveTo(p.x, p.y);
  };
  const move = (e) => {
    if (!drawing.current) return;
    e.preventDefault();
    const ctx = ref.current.getContext("2d");
    const p = pos(e);
    ctx.lineTo(p.x, p.y); ctx.stroke();
    dirty.current = true;
  };
  const end = () => { drawing.current = false; };
  const clear = () => {
    const cv = ref.current, ctx = cv.getContext("2d");
    ctx.fillStyle = "#fff"; ctx.fillRect(0, 0, cv.width, cv.height);
    dirty.current = false;
  };
  if (!open) return null;
  return (
    <Sheet open={open} onClose={onClose} title={title}
      footer={
        <div style={{ display: "flex", gap: 10 }}>
          <Btn kind="ghost" style={{ flex: 1 }} onClick={clear}>Clear</Btn>
          <Btn style={{ flex: 2 }} onClick={() => {
            if (!dirty.current) return;
            onApply(ref.current.toDataURL("image/png"), nowStamp());
            onClose();
          }}>Apply signature</Btn>
        </div>
      }>
      <div style={{ fontSize: 14, color: S.sub, marginBottom: 12 }}>
        Sign with a finger or stylus. The signature and today's date are placed on the acceptance line, and the
        document is locked against silent edits.
      </div>
      <canvas
        ref={ref} width={800} height={300}
        onMouseDown={start} onMouseMove={move} onMouseUp={end} onMouseLeave={end}
        onTouchStart={start} onTouchMove={move} onTouchEnd={end}
        style={{
          width: "100%", height: 190, border: `1.5px dashed ${S.line}`, borderRadius: 12,
          touchAction: "none", background: S.card, display: "block",
        }}
      />
    </Sheet>
  );
}

