/* ==================================================================
   Marketing — the public site. Not a copy of any competitor's layout;
   the section order (hero, feature-by-feature with real screenshots,
   values, pricing, final CTA) is the standard shape most SaaS sites
   converge on for good reason, filled in with RoofStride's own
   content and its own actual screenshots — no stock photography, no
   fabricated mockups.
   ================================================================== */
const MKT = { ink: "#20242A", teal: "#0A9E98", tealDark: "#087F7A", sub: "#5B6470", bg: "#F7F8FA", line: "#E5E7EB" };
const MKT_DISPLAY_FONT = "'Space Grotesk', 'Inter', -apple-system, sans-serif";

/* Loads Space Grotesk once, on the marketing page only — the rest of
   the app stays on the system/Inter stack. A confident, geometric
   display face for headlines only (never body copy) is the one
   deliberate typographic choice on this page; everything else stays
   quiet so that choice reads, rather than fighting for attention with
   five other decisions. */
function useMktFont() {
  useEffect(() => {
    if (document.getElementById("mkt-font-link")) return;
    const link = document.createElement("link");
    link.id = "mkt-font-link";
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700&display=swap";
    document.head.appendChild(link);
  }, []);
}

/* ==================================================================
   Scroll-linked motion — the page's signature element. Not a one-shot
   fade-in-once-then-forget (that was the old Reveal): every section
   continuously tracks its own position in the viewport and answers to
   it the whole time it's on screen, the way apple.com's product pages
   do — content settles into full focus as it centers, and drifts back
   slightly as it leaves, so scrolling itself feels like the thing
   moving the page forward ("stride" literalized). A single imperative
   rAF-driven scroll listener drives every registered section by
   writing directly to element.style — not React state — because a
   piece of state per scroll pixel would re-render the whole page 60
   times a second. `prefers-reduced-motion` short-circuits to fully
   visible/static, honored at the hook level so no page consumer has
   to remember to check it.
   ================================================================== */
const MKT_MOTION = { els: new Set(), raf: null, reduced: false };

function mktMotionTick() {
  MKT_MOTION.raf = null;
  const vh = window.innerHeight;
  MKT_MOTION.els.forEach((el) => {
    const r = el.getBoundingClientRect();
    /* Entry and exit tracked from separate edges, not the element's
       own vertical center (a tall stacked mobile row can be taller
       than the viewport, so its own center never lines up with when
       the top content is actually visible — see the note this
       replaced, still true). But the first version of this fix had
       its own bug: `1 - r.top / (vh * K)` is mathematically anchored
       so entry only reaches 1 once r.top hits exactly 0 — the
       element's top edge at the very TOP of the screen — no matter
       what K is. That's much too late for a natural reveal: readers
       look at the middle of their screen, not the top edge, so
       content stayed dim through the whole time it was comfortably
       in view. Rewritten so entry reaches 1 once the top has scrolled
       up to roughly the vertical middle of the viewport, not the
       very top — full brightness while it's still centered on
       screen, the way it actually reads as "revealed." */
    const entryDoneAt = vh * 0.5;   // top edge at the viewport's middle = fully revealed
    let entry = (vh - r.top) / (vh - entryDoneAt);
    entry = Math.max(0, Math.min(1, entry));
    let exit = 1 - r.bottom / (vh * 0.35);
    exit = Math.max(0, Math.min(1, exit));
    const eased = entry * (1 - exit * 0.4);
    const rise = (1 - entry) * (el.dataset.mktY ? +el.dataset.mktY : 60);
    const scale = 0.86 + eased * 0.14;
    el.style.opacity = String(0.08 + eased * 0.92);
    el.style.transform = `translateY(${rise}px) scale(${scale})`;
    if (el.dataset.mktParallax) {
      const depth = +el.dataset.mktParallax;
      el.style.setProperty("--mkt-parallax", `${(0.5 - entry) * depth}px`);
    }
  });
}
function mktMotionSchedule() {
  if (MKT_MOTION.raf != null) return;
  if (typeof requestAnimationFrame === "function") {
    MKT_MOTION.raf = requestAnimationFrame(mktMotionTick);
  } else {
    MKT_MOTION.raf = setTimeout(mktMotionTick, 16);
  }
}
if (typeof window !== "undefined" && typeof window.addEventListener === "function") {
  window.addEventListener("scroll", mktMotionSchedule, { passive: true });
  window.addEventListener("resize", mktMotionSchedule, { passive: true });
  if (window.matchMedia) {
    try { MKT_MOTION.reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches; }
    catch { /* some test/embed environments don't implement matchMedia fully */ }
  }
}

function Reveal({ children, delay = 0, y = 60, parallax, style, className, id }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || MKT_MOTION.reduced) return;
    el.dataset.mktY = String(y);
    if (parallax) el.dataset.mktParallax = String(parallax);
    /* Deliberately NO CSS transition on opacity/transform here. This is
       the actual bug that made the whole system read as "not really
       happening": a transition fights a value that's already being
       recalculated every animation frame during a scroll — each new
       target arrives before the last one finishes easing toward it, so
       the motion perpetually lags and chases instead of tracking the
       scroll gesture directly. A true scroll-SCRUBBED effect (this is
       how Apple's own product pages, and libraries like GSAP
       ScrollTrigger in scrub mode, actually do it) maps scroll position
       to style values 1:1 with no easing layered on top — the rAF loop
       itself is what already makes it smooth. */
    el.style.transition = "none";
    MKT_MOTION.els.add(el);
    mktMotionSchedule();
    return () => { MKT_MOTION.els.delete(el); };
  }, [y, parallax, delay]);
  return (
    <div ref={ref} className={className ? `mkt-reveal ${className}` : "mkt-reveal"} id={id} style={{
      willChange: "opacity, transform", ...style,
    }}>{children}</div>
  );
}

